import React from "react";
import { useState } from "react";
import "./App.css";
import "./assets/styles/to-do/navbar.css";
import "./assets/styles/to-do/body.css";
import "./assets/styles/to-do/icons.css";
import "./assets/styles/to-do/slide-main-menu.css";
import "./assets/styles/to-do/slide-callendar-menu.css";
import "./assets/styles/to-do/center-container.css";
import "./assets/styles/to-do/cards.css";
import "./assets/styles/to-do/carousel.css";

function App() {
  const [isCallendarMenuVisible, setIsCallendarMenuVisible] = useState(false);
  const [isMenuVisible, setIsMenuVisible] = useState(false);

  const toggleCallendarsMenu = () => {
    setIsCallendarMenuVisible(!isCallendarMenuVisible);
    if (isMenuVisible) {
      setIsMenuVisible(false);
    }
  };

  const toggleMenu = () => {
    setIsMenuVisible(!isMenuVisible);
    if (isCallendarMenuVisible) {
      setIsCallendarMenuVisible(false);
    }
  };

  return (
    <>

    </>
  );
}

export default App;
